class Solution {
public:
    string maxSumOfSquares(int num, int sum) {
        if (sum > 9 * num || sum < 1) return "";

        int k = sum / 9;
        int r = sum % 9;
        int zeros = num - k - (r > 0 ? 1 : 0);

        string result;
        result.reserve(num);
        result.append(k, '9');
        if (r > 0) result.push_back('0' + r);
        result.append(zeros, '0');

        return result;
    }
};
